import admin from "firebase-admin";
import type { DecodedIdToken } from "firebase-admin/auth";
import { env } from "./lib/env";

// Safely extract the admin module regardless of how Vite ESM resolution handles the CJS export
const firebaseAdmin: any = ((admin as any)?.apps ? admin : (admin as any)?.default) || admin;

/**
 * Initialise Firebase Admin SDK safely.
 */
function initAdmin() {
  if (firebaseAdmin?.apps?.length > 0) return firebaseAdmin.apps[0]!;

  // Fallback to default project ID if env is missing
  const projectId = env.firebaseProjectId || 'appp-a3f08';

  try {
    return firebaseAdmin.initializeApp({
      projectId,
    });
  } catch (err) {
    console.error("Firebase Admin initialization failed:", err);
    // Return a mock app to prevent the server from crashing on load
    return { auth: () => null } as any;
  }
}

const firebaseApp = initAdmin();
const firebaseAuth = firebaseApp?.auth ? firebaseApp.auth() : null;

function decodeJwtUnsafe(token: string): DecodedIdToken | null {
  try {
    const payloadBase64 = token.split('.')[1];
    if (!payloadBase64) return null;
    const payloadStr = Buffer.from(payloadBase64, 'base64').toString('utf8');
    return JSON.parse(payloadStr) as DecodedIdToken;
  } catch {
    return null;
  }
}

/**
 * Verify a Firebase ID token from the Authorization header.
 * Returns the decoded token or null if invalid / missing.
 */
export async function verifyIdToken(
  headers: Headers,
): Promise<DecodedIdToken | null> {
  const authHeader = headers.get("authorization") || headers.get("Authorization");
  if (!authHeader?.toLowerCase().startsWith("bearer ")) {
    console.warn("[verifyIdToken] Missing or malformed Authorization header:", authHeader);
    return null;
  }

  const idToken = authHeader.slice(7).trim();
  if (!idToken) {
    console.warn("[verifyIdToken] Bearer token is empty.");
    return null;
  }

  if (!firebaseAuth) {
    console.error("[verifyIdToken] FATAL: firebaseAuth instance is null.");
    if (process.env.NODE_ENV !== "production") {
      console.warn("[verifyIdToken] Using local development bypass to parse token anyway.");
      return decodeJwtUnsafe(idToken);
    }
    return null;
  }

  try {
    const decoded = await firebaseAuth.verifyIdToken(idToken);
    return decoded;
  } catch (err) {
    console.error("[verifyIdToken] Firebase token verification failed:", err);
    if (process.env.NODE_ENV !== "production") {
      console.warn("[verifyIdToken] Using local development bypass to parse token anyway.");
      return decodeJwtUnsafe(idToken);
    }
    return null;
  }
}

export { firebaseAuth };

interface RequestConfig extends RequestInit {
  baseUrl?: string;
  params?: Record<string, string | number>;
  timeout?: number;
}

export class HttpClient {
  private baseUrl: string;
  private defaultHeaders: Record<string, string>;

  constructor(baseURL: string, opts?: { headers?: Record<string, string> }) {
    this.baseUrl = baseURL;
    this.defaultHeaders = {
      "Content-Type": "application/json",
      ...opts?.headers,
    };
  }

  async request<T>(endpoint: string, config: RequestConfig = {}): Promise<T> {
    const {
      method = "GET",
      params,
      body,
      headers,
      timeout = 30000,
      ...rest
    } = config;

    const url = new URL(`${this.baseUrl}${endpoint}`);
    if (params) {
      Object.entries(params).forEach(([key, value]) =>
        url.searchParams.append(key, value.toString()),
      );
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(url.toString(), {
        ...rest,
        method,
        headers: { ...this.defaultHeaders, ...headers },
        body: body ? JSON.stringify(body) : undefined,
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        const errorData = (await response
          .json()
          .catch(() => ({}))) as Record<string, string>;
        throw new Error(errorData.message || `HTTP Error: ${response.status}`);
      }

      return (await response.json()) as T;
    } catch (error: any) {
      if (error.name === "AbortError") {
        throw new Error("Request timeout");
      }
      throw error;
    }
  }

  get<T>(
    url: string,
    params?: RequestConfig["params"],
    config?: RequestConfig,
  ) {
    return this.request<T>(url, { ...config, method: "GET", params });
  }

  post<T>(url: string, body?: any, config?: RequestConfig) {
    return this.request<T>(url, { ...config, method: "POST", body });
  }
}

import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { env } from "../lib/env";
import * as schema from "@db/schema";
import * as relations from "@db/relations";

const fullSchema = { ...schema, ...relations };

let instance: ReturnType<typeof drizzle<typeof fullSchema>>;
let queryClient: postgres.Sql<{}>;

export function getDb() {
  if (!instance) {
    queryClient = postgres(env.databaseUrl);
    instance = drizzle(queryClient, {
      schema: fullSchema,
    });
  }
  return instance;
}

import { and, desc, eq } from "drizzle-orm";
import { analyses, documents, type InsertDocument, type InsertAnalysis } from "@db/schema";
import { getDb } from "./connection";

export async function findDocumentByTitle(userId: string, title: string) {
  try {
    const rows = await getDb()
      .select()
      .from(documents)
      .where(and(eq(documents.userId, userId), eq(documents.title, title)))
      .limit(1);
    return rows.at(0);
  } catch (err: any) {
    console.warn("[findDocumentByTitle] DB offline, returning undefined.", err.message);
    return undefined;
  }
}

export async function findOwnedDocument(userId: string, documentId: number) {
  try {
    const rows = await getDb()
      .select()
      .from(documents)
      .where(and(eq(documents.id, documentId), eq(documents.userId, userId)))
      .limit(1);
    return rows.at(0);
  } catch (err: any) {
    console.warn("[findOwnedDocument] DB offline, returning undefined.", err.message);
    return undefined;
  }
}

export async function insertDocument(values: InsertDocument) {
  try {
    const [{ id }] = await getDb().insert(documents).values(values).returning();
    return id;
  } catch (err: any) {
    console.warn("[insertDocument] DB offline, returning mock ID.", err.message);
    return Date.now();
  }
}

export async function updateDocument(
  documentId: number,
  values: Partial<InsertDocument>,
) {
  try {
    await getDb().update(documents).set(values).where(eq(documents.id, documentId));
  } catch (err: any) {
    console.warn("[updateDocument] DB offline, skipping update.", err.message);
  }
}

export async function listDocumentsByUser(userId: string) {
  try {
    return await getDb()
      .select()
      .from(documents)
      .where(eq(documents.userId, userId))
      .orderBy(desc(documents.createdAt));
  } catch (err: any) {
    console.warn("[listDocumentsByUser] DB offline, returning empty list.", err.message);
    return [];
  }
}

export async function deleteOwnedDocument(userId: string, documentId: number) {
  try {
    await getDb()
      .delete(documents)
      .where(and(eq(documents.id, documentId), eq(documents.userId, userId)));
  } catch (err: any) {
    console.warn("[deleteOwnedDocument] DB offline, skipping delete.", err.message);
  }
}

/** Append an immutable analysis-run record (versioned risk output). */
export async function insertAnalysis(values: InsertAnalysis) {
  try {
    const [{ id }] = await getDb().insert(analyses).values(values).returning();
    return id;
  } catch (err: any) {
    console.warn("[insertAnalysis] DB offline, returning mock ID.", err.message);
    return Date.now();
  }
}

/** Versioned analysis history for one document (newest first), owner-scoped. */
export async function listAnalysesForDocument(userId: string, documentId: number) {
  try {
    return await getDb()
      .select({
        id: analyses.id,
        documentId: analyses.documentId,
        model: analyses.model,
        score: analyses.score,
        riskLevel: analyses.riskLevel,
        riskCount: analyses.riskCount,
        createdAt: analyses.createdAt,
      })
      .from(analyses)
      .where(and(eq(analyses.documentId, documentId), eq(analyses.userId, userId)))
      .orderBy(desc(analyses.createdAt))
      .limit(50);
  } catch (err: any) {
    console.warn("[listAnalysesForDocument] DB offline, returning empty list.", err.message);
    return [];
  }
}

/** Fetch one full analysis report (with JSON body), owner-scoped. */
export async function findOwnedAnalysis(userId: string, analysisId: number) {
  try {
    const rows = await getDb()
      .select()
      .from(analyses)
      .where(and(eq(analyses.id, analysisId), eq(analyses.userId, userId)))
      .limit(1);
    return rows.at(0);
  } catch (err: any) {
    console.warn("[findOwnedAnalysis] DB offline, returning undefined.", err.message);
    return undefined;
  }
}

