export default function ChatAIView({ 
  language,
  contractText, 
  contractTitle, 
  onNavigate,
  initialPrompt,
  onClearInitialPrompt
}: ChatAIViewProps) {
  const t = translations[language];

  // Helper to get translated start message text
  const getStartupMessage = () => {
    if (language === "hi") {
